// 공시팀 전체 목록에 추가
scwin.fn_addDsclTeamAll = function(rowcount) {
    dts_dep.setCellData(2, "VALUE", 'UPTEAM'); //
    dts_dep.setCellData(2, "TEXT", '공시팀 전체');
    dts_dep.setCellData(2, "DEP_CD", 'UPTEAM');
    for (var i = 3; i <= rowcount; i++) {
        dts_dep.setCellData(i, "VALUE", dts_dep1.getCellData(i - 1, "VALUE")); //
        dts_dep.setCellData(i, "TEXT", dts_dep1.getCellData(i - 1, "TEXT"));
        dts_dep.setCellData(i, "DEP_CD", dts_dep1.getCellData(i - 1, "DEP_CD"));
    }
    dts_dep.insertRow();
    dts_dep.setCellData(rowcount + 1, "VALUE", dts_dep1.getCellData(rowcount, "VALUE")); //
    dts_dep.setCellData(rowcount + 1, "TEXT", dts_dep1.getCellData(rowcount, "TEXT"));
    dts_dep.setCellData(rowcount + 1, "DEP_CD", dts_dep1.getCellData(rowcount, "DEP_CD"));
};
scwin.fn_allDisCheck = function() {
    scwin.fn_BsCheck('unCheck');
    scwin.fn_IsCheck('unCheck');
    scwin.fn_BasicCheck('unCheck');
    scwin.fn_KosCheck('unCheck');
};
scwin.fn_allCheck = function() {
    scwin.fn_BsCheck('allCheck');
    scwin.fn_IsCheck('allCheck');
    scwin.fn_BasicCheck('allCheck');
    scwin.fn_KosCheck('allCheck');
};
scwin.fn_BsCheck = function(mode) {
    var checkYN = 'Y';
    var j = 0;
    var flag = 'SHOW';
    for (var i = 0; i < scwin.BsColumnID.length; i++) {
        if (eval('checkbox_' + scwin.BsColumnID[i]).checked) {
            j++;
        }
    }
    if (j == scwin.BsColumnID.length) {
        checkYN = 'N';
    }
    if ((checkYN == 'N' || mode == 'unCheck') && mode != 'allCheck') {
        for (var i = 0; i < scwin.BsColumnID.length; i++) {
            eval('checkbox_' + scwin.BsColumnID[i]).setValue(0);
        }
        flag = 'HIDDEN';
    } else {
        for (var i = 0; i < scwin.BsColumnID.length; i++) {
            eval('checkbox_' + scwin.BsColumnID[i]).setValue(1);
        }
    }
    scwin.fn_BsShowColumn(flag);
};
