scwin.fn_BsShowColumn = function(flag) {
    if (flag == 'SHOW') {
        for (var i = 0; i < scwin.BsColumnID.length; i++) {
            $c.cm.setColumnProp(grd_Grid, scwin.BsColumnID[i], 'Show', true);
        }
    } else {
        for (var i = 0; i < scwin.BsColumnID.length; i++) {
            $c.cm.setColumnProp(grd_Grid, scwin.BsColumnID[i], 'Show', false);
        }
