scwin.fn_getUsrDisclViewerInfo = function(acpt_no) {
    var url = "/IfrsDisclosureStatistics.do?method=usrDisclViewer";
    url += "&ACPT_NO=" + acpt_no;
    var url = "/IfrsDisclosureStatistics.do?method=usrDisclViewer";
    url += "&ACPT_NO=" + acpt_no;
    dts_viewer.DataID = encodeURI(url);
    dts_viewer.Reset();
};
scwin.fn_OpenUsrDisclViewer = async function(flag, acpt_no, discls_doc_no, work_directory) {
    var bPath = work_directory;
    var html_body_url = "/" + ACPT_NO.substring(0, 4) + "/" + ACPT_NO.substring(4, 6) + "/" + ACPT_NO.substring(6, 8) + "/" + ACPT_NO.substring(8) + "/" + discls_doc_no + "/" + acpt_no + ".html";
    var excel_body_url = "/" + ACPT_NO.substring(0, 4) + "/" + ACPT_NO.substring(4, 6) + "/" + ACPT_NO.substring(6, 8) + "/" + ACPT_NO.substring(8) + "/" + discls_doc_no + "/" + acpt_no + ".xls";
    var url = "/dsclproc/JLDSTF10006.jsp?bPath=" + bPath + "&html_body_url=" + html_body_url + "&excel_body_url=" + excel_body_url + "&excel_name=" + scwin.excel_name + "&acpt_no=" + acpt_no;
    await $c.frame.CreateDialogFrame("viewer" + acpt_no, url, "사용자뷰어", 100, 10, 1000, 800, "window");
};
