scwin.grd_Grid_OnUserColor = function(row, colid) {
    var colorName = "#77FF88"; //11FF00";
    var value = "";
    var column = new Array("ASSETS1", "ASSETS2", "LIABILITIES1", "LIABILITIES2", "EQUITY1", "EQUITY2", "CURRENTASSETS1", "CURRENTASSETS2", "NONCURRENTASSETS1", "NONCURRENTASSETS2", "CURRENTLIABILITIES1", "CURRENTLIABILITIES2", "NONCURRENTLIABILITIES1", "NONCURRENTLIABILITIES2", "ISSUEDCAPITAL1", "ISSUEDCAPITAL2", "PROPERTYPLANTEQUIPMENT1", "PROPERTYPLANTEQUIPMENT2", "CAPITALSURPLUS1", "CAPITALSURPLUS2", "ACCOTHCOMINCOME1", "ACCOTHCOMINCOME2", "OWNERSOFPARENT1", "OWNERSOFPARENT2", "NONOWNERSOFPARENT1", "NONOWNERSOFPARENT2", "REVENUE1", "REVENUE2", "REVENUE3", "REVENUE4", "COSTOFSALES1", "COSTOFSALES2", "COSTOFSALES3", "COSTOFSALES4", "GROSSPROFIT1", "GROSSPROFIT2", "GROSSPROFIT3", "GROSSPROFIT4", "OPERATINGINCOMELOSS1", "OPERATINGINCOMELOSS2", "OPERATINGINCOMELOSS3", "OPERATINGINCOMELOSS4", "INCOMETAXESEXPENSES1", "INCOMETAXESEXPENSES2", "INCOMETAXESEXPENSES3", "INCOMETAXESEXPENSES4", "PROFITLOSSBFTAX1", "PROFITLOSSBFTAX2", "PROFITLOSSBFTAX3", "PROFITLOSSBFTAX4", "FINANCEINCOME1", "FINANCEINCOME2", "FINANCEINCOME3", "FINANCEINCOME4", "COMPREHENSIVEINCOME1", "COMPREHENSIVEINCOME2", "COMPREHENSIVEINCOME3", "COMPREHENSIVEINCOME4", "PROFITLOSS1", "PROFITLOSS2", "PROFITLOSS3", "PROFITLOSS4");
    var cell = "";
    if (dts_Grid.getCellData(row, "ACPT_NO") == null || dts_Grid.getCellData(row, "ACPT_NO") == undefined) {
        return;
        colorName = "#ffffff"; // 데이타가 없으면 흰색으로

    }

    //회사정보결산월과 xbrl 재무정보의 결산월 비교
    if (colid == "acolor100") {
        var mm1 = dts_Grid.getCellData(row, "ACNTCLS_MM");
        var mm2 = dts_Grid.getCellData(row, "ACNTCLS_MMDD1");
        if (scwin.colorCnt > 0 && mm1 != mm2) {
            return colorName; // 연두색
        } else {
            return "#ffffff";
        }
    }
    if (colid == "acolor101") {
        check1 = dts_Grid.getCellData(row, "AUDT_OPIN_TP_NM");
        if (scwin.colorCnt > 0 && check1 != "적정" && check1 != "의견거절" && check1 != "한정" && check1 != "부적정") {
            return colorName; // 연두색
        } else {
            return "#ffffff";
        }
    }
    for (var i = 0; i < column.length; i++) {
        cell = "acolor" + (i + 1);
        if (colid == cell) {
            //모든 필드 '0' or '' 인지 체크한다.
            value.setValue(dts_Grid.getCellData(row, column[i]));
            if (scwin.colorCnt > 0 && colid == 'acolor1') {
                //자산총계 = 부채총계 + 자본총계
                value1 = parseInt(dts_Grid.getCellData(row, "ASSETS1"));
                value2 = parseInt(dts_Grid.getCellData(row, "LIABILITIES1"));
                value3 = parseInt(dts_Grid.getCellData(row, "EQUITY1"));
                value4 = parseInt(dts_Grid.getCellData(row, "CURRENTASSETS1")); //유동자산
                value5 = parseInt(dts_Grid.getCellData(row, "NONCURRENTASSETS1")); //비유동자산
                if ((value1 != value2 + value3) || (value1 != value4 + value5)) {
                    return colorName;
                } else {
                    return "#ffffff";
                }
            } else if (scwin.colorCnt > 0 && colid == 'acolor2') {
                //자산총계 = 부채총계 + 자본총계
                value1 = parseInt(dts_Grid.getCellData(row, "ASSETS2"));
                value2 = parseInt(dts_Grid.getCellData(row, "LIABILITIES2"));
                value3 = parseInt(dts_Grid.getCellData(row, "EQUITY2"));
                value4 = parseInt(dts_Grid.getCellData(row, "CURRENTASSETS2")); //유동자산
                value5 = parseInt(dts_Grid.getCellData(row, "NONCURRENTASSETS2")); //비유동자산
                if ((value1 != value2 + value3) || (value1 != value4 + value5)) {
                    return colorName;
                } else {
                    return "#ffffff";
                }
            } else if (scwin.colorCnt > 0 && colid == 'acolor3') {
                //부채총계 = 유동부채 + 비유동부채
                value1 = parseInt(dts_Grid.getCellData(row, "LIABILITIES1"));
                value2 = parseInt(dts_Grid.getCellData(row, "CURRENTLIABILITIES1"));
                value3 = parseInt(dts_Grid.getCellData(row, "NONCURRENTLIABILITIES1"));
                if (value1 != value2 + value3) {
                    return colorName;
                } else {
                    return "#ffffff";
                }
            } else if (scwin.colorCnt > 0 && colid == 'acolor4') {
                //부채총계 = 유동부채 + 비유동부채
                value1 = parseInt(dts_Grid.getCellData(row, "LIABILITIES2"));
                value2 = parseInt(dts_Grid.getCellData(row, "CURRENTLIABILITIES2"));
                value3 = parseInt(dts_Grid.getCellData(row, "NONCURRENTLIABILITIES2"));
                if (value1 != value2 + value3) {
                    return colorName;
                } else {
                    return "#ffffff";
                }
            } else {
                return "#ffffff";
            }
            //}

        }
    }
};
